package com.github.cubeee.bufftracker;

import com.github.cubeee.bufftracker.model.Buff;
import com.github.cubeee.bufftracker.model.BuffIcon;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.BasicStroke;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.*;

/**
 * Item and sprite icons for every buff. Used on the client thread only.
 */
@Singleton
class BuffIconStore {

    private final ItemManager itemManager;
    private final SpriteManager spriteManager;
    private final BuffTrackerConfig config;

    // Item images are filled in asynchronously; only loaded ones are handed out
    private final Map<Buff, BufferedImage> images = new EnumMap<>(Buff.class);
    private final Map<Buff, BufferedImage> scaledImages = new EnumMap<>(Buff.class);
    private BufferedImage placeholderImage;
    private boolean started;
    private Runnable changeListener = () -> {};

    @Inject
    BuffIconStore(ItemManager itemManager, SpriteManager spriteManager, BuffTrackerConfig config) {
        this.itemManager = itemManager;
        this.spriteManager = spriteManager;
        this.config = config;
    }

    void setChangeListener(Runnable changeListener) {
        this.changeListener = changeListener;
    }

    void startUp() {
        started = true;
        for (Buff buff : Buff.values()) {
            BuffIcon icon = buff.getIcon();
            if (icon.getSource() == BuffIcon.Source.SPRITE) {
                // Retried on the client thread until the sprite is available
                spriteManager.getSpriteAsync(icon.getId(), 0, image -> onImageLoaded(buff, image));
            } else {
                AsyncBufferedImage image = itemManager.getImage(icon.getId());
                image.onLoaded(() -> onImageLoaded(buff, image));
            }
        }
    }

    void shutDown() {
        started = false;
        images.clear();
        scaledImages.clear();
        placeholderImage = null;
        changeListener = () -> {};
    }

    private void onImageLoaded(Buff buff, BufferedImage image) {
        if (!started) {
            // Shut down while loading
            return;
        }
        images.put(buff, image);
        scaledImages.remove(buff);
        changeListener.run();
    }

    /**
     * Returns null while the item image is still loading.
     */
    BufferedImage getScaledImage(Buff buff) {
        BufferedImage scaled = scaledImages.get(buff);
        if (scaled == null) {
            BufferedImage image = images.get(buff);
            if (image == null) {
                return null;
            }
            scaled = scaleImage(image);
            scaledImages.put(buff, scaled);
        }
        return scaled;
    }

    void rescale() {
        scaledImages.clear();
        placeholderImage = null;
    }

    Map<Buff, BufferedImage> snapshot() {
        return new EnumMap<>(images);
    }

    // Shown while an item image is loading, so the box always has something to show
    BufferedImage getPlaceholderImage() {
        if (placeholderImage == null) {
            placeholderImage = createPlaceholderImage(config.buffIconSize());
        }
        return placeholderImage;
    }

    private static BufferedImage createPlaceholderImage(int size) {
        BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try {
            graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            graphics.setColor(ColorScheme.LIGHT_GRAY_COLOR);

            float stroke = Math.max(1f, size / 16f);
            graphics.setStroke(new BasicStroke(stroke));
            float inset = stroke / 2;
            float arc = size / 4f;
            graphics.draw(new RoundRectangle2D.Float(inset, inset, size - stroke, size - stroke, arc, arc));

            graphics.setFont(new Font(Font.DIALOG, Font.BOLD, Math.max(8, Math.round(size * 0.65f))));
            FontMetrics metrics = graphics.getFontMetrics();
            int textX = (size - metrics.stringWidth("?")) / 2;
            int textY = (size - metrics.getHeight()) / 2 + metrics.getAscent();
            graphics.drawString("?", textX, textY);
        } finally {
            graphics.dispose();
        }
        return image;
    }

    // Fits the image inside the icon size, keeping its aspect ratio
    private BufferedImage scaleImage(BufferedImage image) {
        int targetSize = config.buffIconSize();
        return ImageUtil.resizeImage(image, targetSize, targetSize, true);
    }
}

package com.github.cubeee.bufftracker;

import com.github.cubeee.bufftracker.config.ConfigKeys;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.FontType;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

import java.awt.Color;

@ConfigGroup(ConfigKeys.PLUGIN_CONFIG_GROUP_NAME)
public interface BuffTrackerConfig extends Config
{

	//
	// Sidepanel
	//

	@ConfigSection(
		name = "Panel",
		description = "",
		position = ConfigKeys.PANEL_SECTION_POSITION,
		closedByDefault = true
	)
	String PANEL_SECTION = "Panel";

	@ConfigSection(
		name = "Buffs",
		description = "",
		position = ConfigKeys.BUFFS_SECTION_POSITION
	)
	String BUFFS_SECTION = "Buffs";

	@ConfigSection(
		name = "Hotkeys",
		description = "",
		position = ConfigKeys.HOTKEYS_SECTION_POSITION
	)
	String HOTKEYS_SECTION = "Hotkeys";

	@ConfigItem(
		keyName = ConfigKeys.SHOW_PANEL,
		name = "Show sidepanel",
		description = "Disable if you don't want to see the sidepanel icon",
		section = PANEL_SECTION,
		position = 10
	)
	default boolean showPanel() {
		return true;
	}

	@ConfigItem(
		keyName = ConfigKeys.PANEL_PRIORITY,
		name = "Panel priority",
		description = "Sorting priority of the panel in the sidebar",
		section = PANEL_SECTION,
		position = 20
	)
	@Range(min = -10, max = 20)
	default int getPanelPriority() {
		return 10;
	}

	//
	// Hotkeys
	//

	@ConfigItem(
		keyName = ConfigKeys.CYCLE_GROUP_HOTKEY,
		name = "Cycle group",
		description = "Show the next group. Also works while typing in chat, so a key combination such as Ctrl+G is recommended",
		section = HOTKEYS_SECTION,
		position = 10
	)
	default Keybind cycleGroupHotkey() {
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = ConfigKeys.TOGGLE_VISIBILITY_HOTKEY,
		name = "Toggle visibility",
		description = "Hide the visible group, or show the last visible group again. Also works while typing in chat, so a key combination such as Ctrl+H is recommended",
		section = HOTKEYS_SECTION,
		position = 20
	)
	default Keybind toggleVisibilityHotkey() {
		return Keybind.NOT_SET;
	}

	//
	// Buffs
	//

	@ConfigItem(
		keyName = ConfigKeys.BUFF_ICON_SIZE,
		name = "Icon size",
		description = "",
		section = BUFFS_SECTION,
		position = 100
	)
	@Range(min = 2, max = 100)
	default int buffIconSize() {
		return 24;
	}

	@ConfigItem(
		keyName = ConfigKeys.BUFF_FONT,
		name = "Font",
		description = "",
		section = BUFFS_SECTION,
		position = 150
	)
	default FontType getFont() {
		return FontType.SMALL;
	}

	@ConfigItem(
		keyName = ConfigKeys.BUFF_PRESENT_COLOR,
		name = "Present color",
		description = "Background color of a present buff",
		section = BUFFS_SECTION,
		position = 300
	)
	@Alpha
	default Color buffPresentColor() {
		Color baseColor = Color.GREEN;
		return new Color(baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(), 70);
	}

	@ConfigItem(
		keyName = ConfigKeys.BUFF_MISSING_COLOR,
		name = "Missing color",
		description = "Background color of a missing buff",
		section = BUFFS_SECTION,
		position = 400
	)
	@Alpha
	default Color buffMissingColor() {
		Color baseColor = Color.RED;
		return new Color(baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(), 70);
	}

}

package com.github.cubeee.bufftracker;

import com.github.cubeee.bufftracker.config.ConfigKeys;
import com.github.cubeee.bufftracker.model.Buff;
import com.google.inject.Provides;

import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.HotkeyListener;

@Slf4j
@PluginDescriptor(
	name = "Buff Tracker",
	description = "Track groups of buffs such as potions and thralls, and see which ones are missing",
	tags = {"buff", "potion", "thrall", "timers", "divine", "antifire", "stamina"}
)
public class BuffTrackerPlugin extends Plugin {

	@Inject
	private ClientThread clientThread;

	@Inject
	private BuffIconStore iconStore;

	@Inject
	private GroupStore groupStore;

	@Inject
	private PanelController panelController;

	@Inject
	private BuffTrackerConfig config;

	@Inject
	private KeyManager keyManager;

	// Client thread only; set when a var changed, so the visible group's presence is refreshed once per cycle
	private boolean presenceDirty;

	private final HotkeyListener cycleGroupListener = new HotkeyListener(() -> config.cycleGroupHotkey()) {
		@Override
		public void hotkeyPressed() {
			clientThread.invokeLater(groupStore::cycleVisible);
		}
	};

	private final HotkeyListener toggleVisibilityListener = new HotkeyListener(() -> config.toggleVisibilityHotkey()) {
		@Override
		public void hotkeyPressed() {
			clientThread.invokeLater(groupStore::toggleVisibility);
		}
	};

	@Override
	protected void startUp() {
		panelController.startUp();

		// The stores are only used on the client thread. Queued after any pending shutDown() work, so a quick
		// restart can't have its listeners cleared by the previous run.
		clientThread.invokeLater(() -> {
			iconStore.setChangeListener(panelController::refreshIcons);
			groupStore.setChangeListener(panelController::refreshGroups);
			groupStore.setReloadListener(panelController::replaceGroups);
			groupStore.load();
			iconStore.startUp();
			panelController.refreshGroups();
		});

		keyManager.registerKeyListener(cycleGroupListener);
		keyManager.registerKeyListener(toggleVisibilityListener);
	}

	@Override
	protected void shutDown() {
		keyManager.unregisterKeyListener(cycleGroupListener);
		keyManager.unregisterKeyListener(toggleVisibilityListener);

		panelController.shutDown();
		clientThread.invokeLater(() -> {
			groupStore.clear();
			iconStore.shutDown();
		});
	}

	@Override
	public void resetConfiguration() {
		// Groups aren't config items, so the config panel's reset skips them
		clientThread.invokeLater(groupStore::reset);
	}

	@Provides
	@SuppressWarnings("unused")
	BuffTrackerConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(BuffTrackerConfig.class);
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onConfigChanged(ConfigChanged event) {
		if (!ConfigKeys.PLUGIN_CONFIG_GROUP_NAME.equals(event.getGroup())) {
			return;
		}

		// Groups are saved under this config group too. Most writes are the plugin's own, but they can also come
		// from elsewhere, e.g. config sync from another client.
		if (ConfigKeys.GROUPS.equals(event.getKey())) {
			clientThread.invoke(groupStore::reloadIfChanged);
			return;
		}

		if (ConfigKeys.BUFF_ICON_SIZE.equals(event.getKey())) {
			clientThread.invoke(() -> {
				iconStore.rescale();
				groupStore.invalidateLayouts();
			});
			return;
		}

		if (ConfigKeys.BUFF_FONT.equals(event.getKey())) {
			clientThread.invoke(groupStore::invalidateLayouts);
			return;
		}

		// The navigation button is only touched on the EDT; ConfigChanged can come from any thread
		String key = event.getKey();
		SwingUtilities.invokeLater(() -> panelController.onConfigChanged(key));
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onProfileChanged(ProfileChanged event) {
		// Groups and config values are stored per profile
		SwingUtilities.invokeLater(panelController::onProfileChanged);
		clientThread.invokeLater(() -> {
			iconStore.rescale();
			groupStore.reload();
		});
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onVarbitChanged(VarbitChanged event) {
		// Also posted for varp changes. Many can arrive in one cycle, so the refresh is batched in onClientTick.
		if (Buff.isTracked(event.getVarbitId(), event.getVarpId())) {
			presenceDirty = true;
		}
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onGameStateChanged(GameStateChanged event) {
		// Logging out or hopping may reset vars
		presenceDirty = true;
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onClientTick(ClientTick event) {
		if (presenceDirty) {
			presenceDirty = false;
			groupStore.refreshPresence(groupStore.getVisibleGroup());
		}
	}
}

package com.github.cubeee.bufftracker;

import com.github.cubeee.bufftracker.model.Buff;
import com.github.cubeee.bufftracker.model.BuffGroup;
import com.github.cubeee.bufftracker.model.BuffWrapper;
import com.github.cubeee.bufftracker.config.DisplayMode;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.overlay.components.ComponentOrientation;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.function.*;

/**
 * Group changes requested by the panel. Called on the EDT; applied on the client thread, where groups are read.
 */
@Singleton
public class GroupActions {

    private final ClientThread clientThread;
    private final GroupStore groupStore;

    @Inject
    GroupActions(ClientThread clientThread, GroupStore groupStore) {
        this.clientThread = clientThread;
        this.groupStore = groupStore;
    }

    public void createGroup() {
        clientThread.invokeLater(groupStore::create);
    }

    public void deleteGroup(String id) {
        clientThread.invokeLater(() -> groupStore.delete(id));
    }

    public void setName(String id, String name) {
        modifyGroup(id, group -> group.setName(name));
    }

    public void setVisible(String id, boolean visible) {
        clientThread.invokeLater(() -> groupStore.setVisible(id, visible));
    }

    public void setDisplayMode(String id, DisplayMode mode) {
        modifyGroup(id, group -> group.setDisplayMode(mode));
    }

    public void setDirection(String id, ComponentOrientation orientation, boolean reversed) {
        modifyGroup(id, group -> {
            group.setOrientation(orientation);
            group.setReversed(reversed);
        });
    }

    public void setMissingOnly(String id, boolean missingOnly) {
        modifyGroup(id, group -> group.setMissingOnly(missingOnly));
    }

    public void setFlashMissing(String id, boolean flashMissing) {
        modifyGroup(id, group -> group.setFlashMissing(flashMissing));
    }

    public void addBuff(String id, Buff buff) {
        modifyGroup(id, group -> {
            if (!group.contains(buff)) {
                // GroupStore.modify() refreshes presence right after
                group.getBuffs().add(new BuffWrapper(buff, false));
            }
        });
    }

    public void removeBuff(String id, Buff buff) {
        modifyGroup(id, group -> group.getBuffs().removeIf(wrapper -> wrapper.getBuff() == buff));
    }

    public void moveBuff(String id, Buff buff, int delta) {
        modifyGroup(id, group -> {
            List<BuffWrapper> buffs = group.getBuffs();
            for (int i = 0; i < buffs.size(); i++) {
                if (buffs.get(i).getBuff() == buff) {
                    int target = i + delta;
                    if (target >= 0 && target < buffs.size()) {
                        Collections.swap(buffs, i, target);
                    }
                    return;
                }
            }
        });
    }

    private void modifyGroup(String id, Consumer<BuffGroup> modification) {
        clientThread.invokeLater(() -> groupStore.modify(id, modification));
    }
}

package com.github.cubeee.bufftracker;

import com.github.cubeee.bufftracker.model.BuffGroup;
import com.github.cubeee.bufftracker.model.BuffWrapper;
import com.github.cubeee.bufftracker.overlay.BuffComponent;
import net.runelite.api.Client;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentOrientation;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.Text;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.*;

public class GroupOverlay extends Overlay {

    private final BuffGroup group;
    private final BuffIconStore iconStore;
    private final BuffTrackerConfig config;
    private final RuneLiteConfig runeLiteConfig;
    private final TooltipManager tooltipManager;
    private final Client client;

    private static final int PADDING = 6;

    // Measured lazily on the client thread and kept until invalidateLayout()
    private Dimension boxSize;
    private Dimension fullSize;
    // One per member in group order, built with the layout; only positions, colors and images change between frames
    private final List<BuffComponent> components = new ArrayList<>();

    GroupOverlay(
            Plugin plugin,
            BuffGroup group,
            BuffIconStore iconStore,
            BuffTrackerConfig config,
            RuneLiteConfig runeLiteConfig,
            TooltipManager tooltipManager,
            Client client
    ) {
        super(plugin);
        this.group = group;
        this.iconStore = iconStore;
        this.config = config;
        this.runeLiteConfig = runeLiteConfig;
        this.tooltipManager = tooltipManager;
        this.client = client;

        setPosition(OverlayPosition.TOP_LEFT);
        setDragTargetable(false);
        setResizable(false);
    }

    @Override
    public String getName() {
        return "BuffTrackerGroup_" + group.getId();
    }

    @Override
    public Dimension getPreferredSize() {
        // Size is derived from the boxes; ignore any previously saved user size
        return null;
    }

    /**
     * Forgets the measured size; call when the group's members, display mode or orientation, or the font or icon
     * size change.
     */
    void invalidateLayout() {
        boxSize = null;
        fullSize = null;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        List<BuffWrapper> buffs = group.getBuffs();
        if (!group.isVisible() || buffs.isEmpty()) {
            return null;
        }

        // The size check guards against a member change that missed invalidateLayout()
        if (boxSize == null || components.size() != buffs.size()) {
            Font font = config.getFont().getFont();
            // Measure every member, not just the visible ones, so the overlay keeps the same size (and saved
            // position) when "Show missing only" hides boxes
            boxSize = measureBoxSize(graphics.getFontMetrics(font));
            fullSize = getFullSize(buffs.size(), boxSize);
            createComponents(buffs, font);
        }

        BuffWrapper hovered = renderBoxes(graphics, buffs);
        if (hovered != null) {
            // Tags typed into the group name would be parsed by the tooltip, and malformed ones like <col=xyz>
            // throw while rendering it. The tooltip doesn't understand escapes like <lt>, so strip them instead.
            tooltipManager.add(new Tooltip(Text.removeTags(group.getName()) + ": " + hovered.getBuff().getName()));
        }

        // The full size even when boxes are hidden, so the overlay doesn't move when they come back
        return fullSize;
    }

    /**
     * Draws the shown boxes one after another and returns the hovered buff, if any.
     */
    private BuffWrapper renderBoxes(Graphics2D graphics, List<BuffWrapper> buffs) {
        // Component bounds are relative to the overlay, so move the mouse into the same space
        net.runelite.api.Point mouseCanvasPosition = client.getMouseCanvasPosition();
        Rectangle overlayBounds = getBounds();
        int mouseX = mouseCanvasPosition.getX() - overlayBounds.x;
        int mouseY = mouseCanvasPosition.getY() - overlayBounds.y;
        BuffWrapper hovered = null;

        Color presentColor = config.buffPresentColor();
        Color missingColor = getMissingColor();
        boolean horizontal = group.getOrientation() == ComponentOrientation.HORIZONTAL;
        int boxX = 0;
        int boxY = 0;
        int count = buffs.size();
        for (int i = 0; i < count; i++) {
            int index = group.isReversed() ? count - 1 - i : i;
            BuffWrapper buff = buffs.get(index);
            if (group.isMissingOnly() && buff.isPresent()) {
                continue;
            }

            BuffComponent component = components.get(index);
            component.setBackgroundColor(buff.isPresent() ? presentColor : missingColor);
            // Item images finish loading after the layout is built
            component.setImage(getImage(buff));
            component.setLocation(boxX, boxY);
            component.render(graphics);
            if (component.getBounds().contains(mouseX, mouseY)) {
                hovered = buff;
            }

            // Boxes touch, without a gap
            if (horizontal) {
                boxX += boxSize.width;
            } else {
                boxY += boxSize.height;
            }
        }
        return hovered;
    }

    private Dimension measureBoxSize(FontMetrics metrics) {
        boolean showText = group.isShowText();
        int textWidth = 0;
        if (showText) {
            for (BuffWrapper buff : group.getBuffs()) {
                textWidth = Math.max(textWidth, metrics.stringWidth(buff.getBuff().getName()));
            }
        }
        int textHeight = showText ? metrics.getHeight() : 0;
        int textRightPadding = showText ? PADDING : 0;

        boolean showIcon = group.isShowIcon();
        // Fixed square slot; scaled icons and the placeholder always fit in it
        int iconSize = showIcon ? config.buffIconSize() : 0;
        int iconPadding = showIcon ? PADDING : 0;

        int width = PADDING + iconSize + iconPadding + textWidth + textRightPadding;
        int height = PADDING + Math.max(textHeight, iconSize) + PADDING;
        return new Dimension(width, height);
    }

    private Dimension getFullSize(int count, Dimension boxSize) {
        return group.getOrientation() == ComponentOrientation.HORIZONTAL
                ? new Dimension(count * boxSize.width, boxSize.height)
                : new Dimension(boxSize.width, count * boxSize.height);
    }

    private Color getMissingColor() {
        int flashRate = 40;
        boolean isFlashing = group.isFlashMissing() && client.getGameCycle() % flashRate >= (flashRate / 2);
        // Alternates with RuneLite's "Overlay color", like any other overlay background
        return isFlashing ? runeLiteConfig.overlayBackgroundColor() : config.buffMissingColor();
    }

    private void createComponents(List<BuffWrapper> buffs, Font font) {
        components.clear();
        int iconSize = config.buffIconSize();
        for (BuffWrapper buff : buffs) {
            BuffComponent component = new BuffComponent();
            // Same font the box was measured with
            component.setFont(font);
            component.setPadding(PADDING);
            component.setIconSize(iconSize);
            component.setText(group.isShowText() ? buff.getBuff().getName() : null);
            component.setPreferredSize(boxSize);
            components.add(component);
        }
    }

    // Null when the group shows text only
    private BufferedImage getImage(BuffWrapper buff) {
        if (!group.isShowIcon()) {
            return null;
        }
        BufferedImage image = iconStore.getScaledImage(buff.getBuff());
        return image != null ? image : iconStore.getPlaceholderImage();
    }
}

package com.github.cubeee.bufftracker;

import com.github.cubeee.bufftracker.model.BuffGroup;
import net.runelite.api.Client;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Holds what every group overlay needs, so the store only deals with groups.
 */
@Singleton
class GroupOverlayFactory {

    private final BuffTrackerPlugin plugin;
    private final BuffIconStore iconStore;
    private final BuffTrackerConfig config;
    private final RuneLiteConfig runeLiteConfig;
    private final TooltipManager tooltipManager;
    private final Client client;

    @Inject
    GroupOverlayFactory(
            BuffTrackerPlugin plugin,
            BuffIconStore iconStore,
            BuffTrackerConfig config,
            RuneLiteConfig runeLiteConfig,
            TooltipManager tooltipManager,
            Client client
    ) {
        this.plugin = plugin;
        this.iconStore = iconStore;
        this.config = config;
        this.runeLiteConfig = runeLiteConfig;
        this.tooltipManager = tooltipManager;
        this.client = client;
    }

    GroupOverlay create(BuffGroup group) {
        return new GroupOverlay(plugin, group, iconStore, config, runeLiteConfig, tooltipManager, client);
    }
}

package com.github.cubeee.bufftracker;

import com.github.cubeee.bufftracker.model.BuffGroup;
import com.github.cubeee.bufftracker.model.BuffWrapper;
import com.github.cubeee.bufftracker.model.SavedGroup;
import com.github.cubeee.bufftracker.config.ConfigKeys;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ConfigProfile;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.function.*;

/**
 * The groups and their overlays. Used on the client thread only.
 */
@Slf4j
@Singleton
class GroupStore {

    private final ConfigManager configManager;
    private final Gson gson;
    private final OverlayManager overlayManager;
    private final GroupOverlayFactory overlayFactory;
    private final Client client;

    private final List<BuffGroup> groups = new ArrayList<>();
    private final Map<String, GroupOverlay> overlays = new HashMap<>();
    // Restored by toggleVisibility() after the visible group has been hidden
    private String lastVisibleId;
    // The groups JSON last read from or written to the config, to tell outside changes from our own
    private String savedJson;
    // The config profile the groups were loaded from
    private long loadedProfileId;
    private Runnable changeListener = () -> {};
    // Told when the groups were replaced wholesale, rather than changed
    private Runnable reloadListener = () -> {};

    @Inject
    GroupStore(
            ConfigManager configManager,
            Gson gson,
            OverlayManager overlayManager,
            GroupOverlayFactory overlayFactory,
            Client client
    ) {
        this.configManager = configManager;
        this.gson = gson;
        this.overlayManager = overlayManager;
        this.overlayFactory = overlayFactory;
        this.client = client;
    }

    void setChangeListener(Runnable changeListener) {
        this.changeListener = changeListener;
    }

    void setReloadListener(Runnable reloadListener) {
        this.reloadListener = reloadListener;
    }

    void load() {
        // A reload for a config change may come before the startup load
        unload();
        loadedProfileId = getProfileId();
        savedJson = configManager.getConfiguration(ConfigKeys.PLUGIN_CONFIG_GROUP_NAME, ConfigKeys.GROUPS);
        groups.addAll(parseGroups(savedJson));

        // Only one group may be visible; keep the first if older data has several
        boolean visibleFound = false;
        for (BuffGroup group : groups) {
            if (group.isVisible() && visibleFound) {
                group.setVisible(false);
            }
            visibleFound |= group.isVisible();
        }

        for (BuffGroup group : groups) {
            refreshPresence(group);
            addOverlay(group);
        }
    }

    private List<BuffGroup> parseGroups(String json) {
        if (json == null || json.isEmpty()) {
            return Collections.emptyList();
        }

        List<SavedGroup> saved;
        try {
            saved = gson.fromJson(json, new TypeToken<List<SavedGroup>>() {}.getType());
        } catch (JsonSyntaxException e) {
            log.warn("Failed to parse saved groups, ignoring them", e);
            return Collections.emptyList();
        }
        if (saved == null) {
            return Collections.emptyList();
        }

        List<BuffGroup> loaded = new ArrayList<>();
        Set<String> ids = new HashSet<>();
        for (SavedGroup savedGroup : saved) {
            if (savedGroup == null) {
                continue;
            }
            BuffGroup group = savedGroup.toGroup();
            // Skip duplicate ids; they would share an overlay position
            if (ids.add(group.getId())) {
                loaded.add(group);
            }
        }
        return loaded;
    }

    void clear() {
        unload();
        changeListener = () -> {};
        reloadListener = () -> {};
    }

    /**
     * Replaces the groups with the ones saved in the current config profile.
     */
    void reload() {
        load();
        // Only the panel needs updating; saving would just write back what was read
        reloadListener.run();
    }

    /**
     * Reloads the groups if the saved ones differ from what was last read or written, i.e. they were changed by
     * something other than this store.
     */
    void reloadIfChanged() {
        if (getProfileId() != loadedProfileId) {
            // Switching profiles also posts this. ProfileChanged reloads the groups then; reloading here too would
            // treat the old profile's groups as deleted and reset their positions in the new profile.
            return;
        }
        String json = configManager.getConfiguration(ConfigKeys.PLUGIN_CONFIG_GROUP_NAME, ConfigKeys.GROUPS);
        if (Objects.equals(json, savedJson)) {
            return;
        }
        Map<String, GroupOverlay> removed = new HashMap<>(overlays);
        reload();
        // Forget the positions of groups deleted elsewhere, e.g. by editing the config by hand, as delete() would
        removed.keySet().removeAll(overlays.keySet());
        for (GroupOverlay overlay : removed.values()) {
            overlayManager.resetOverlay(overlay);
        }
    }

    private long getProfileId() {
        ConfigProfile profile = configManager.getProfile();
        return profile != null ? profile.getId() : -1;
    }

    private void unload() {
        // Only the visible group's overlay is added; removing the others does nothing
        for (GroupOverlay overlay : overlays.values()) {
            overlayManager.remove(overlay);
        }
        overlays.clear();
        groups.clear();
        lastVisibleId = null;
    }

    // Called when the plugin config is reset; works whether or not the plugin is running
    void reset() {
        // Read from the config rather than the live overlays, which don't exist while the plugin is off.
        // Resetting an overlay that was never added just clears its saved position.
        for (BuffGroup group : parseGroups(configManager.getConfiguration(ConfigKeys.PLUGIN_CONFIG_GROUP_NAME, ConfigKeys.GROUPS))) {
            overlayManager.resetOverlay(overlayFactory.create(group));
        }
        unload();
        changed();
    }

    List<BuffGroup> snapshot() {
        List<BuffGroup> snapshot = new ArrayList<>(groups.size());
        for (BuffGroup group : groups) {
            snapshot.add(group.copy());
        }
        return snapshot;
    }

    void create() {
        boolean visible = groups.stream().noneMatch(BuffGroup::isVisible);
        BuffGroup group = new BuffGroup(
                UUID.randomUUID().toString(),
                "New group",
                BuffGroup.DEFAULT_DISPLAY_MODE,
                visible,
                false,
                BuffGroup.DEFAULT_ORIENTATION,
                List.of()
        );
        groups.add(group);
        addOverlay(group);
        changed();
    }

    void delete(String id) {
        groups.removeIf(group -> group.getId().equals(id));
        GroupOverlay overlay = overlays.remove(id);
        if (overlay != null) {
            // Forget the saved position so it doesn't linger in the config
            overlayManager.resetOverlay(overlay);
            overlayManager.remove(overlay);
        }
        changed();
    }

    /**
     * Showing a group hides all others, as only one group may be visible at a time.
     */
    void setVisible(String id, boolean visible) {
        // A stale panel may still show a group that's gone, e.g. right after a profile switch
        int index = indexOf(id);
        if (index < 0 || groups.get(index).isVisible() == visible) {
            // The panel's eye button toggled itself when clicked; send the actual state back to it
            changeListener.run();
            return;
        }
        BuffGroup target = groups.get(index);
        // Only one group is ever visible: the target when hiding, or the one it replaces when showing
        BuffGroup previous = getVisibleGroup();
        if (previous != null) {
            lastVisibleId = previous.getId();
            previous.setVisible(false);
            overlayManager.remove(overlays.get(previous.getId()));
        }
        if (visible) {
            // Hidden groups aren't refreshed when vars change, so their state may be stale
            refreshPresence(target);
            target.setVisible(true);
            overlayManager.add(overlays.get(target.getId()));
        }
        changed();
    }

    void cycleVisible() {
        if (groups.isEmpty()) {
            return;
        }
        int current = indexOf(findVisibleId());
        if (current < 0) {
            // Nothing shown: continue from the group that was last visible
            current = indexOf(lastVisibleId);
        }
        BuffGroup next = groups.get((current + 1) % groups.size());
        setVisible(next.getId(), true);
    }

    void toggleVisibility() {
        String visibleId = findVisibleId();
        if (visibleId != null) {
            setVisible(visibleId, false);
            return;
        }
        if (groups.isEmpty()) {
            return;
        }
        String id = indexOf(lastVisibleId) >= 0 ? lastVisibleId : groups.get(0).getId();
        setVisible(id, true);
    }

    BuffGroup getVisibleGroup() {
        for (BuffGroup group : groups) {
            if (group.isVisible()) {
                return group;
            }
        }
        return null;
    }

    private String findVisibleId() {
        BuffGroup visible = getVisibleGroup();
        return visible != null ? visible.getId() : null;
    }

    private int indexOf(String id) {
        if (id == null) {
            return -1;
        }
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).getId().equals(id)) {
                return i;
            }
        }
        return -1;
    }

    void modify(String id, Consumer<BuffGroup> modification) {
        for (BuffGroup group : groups) {
            if (group.getId().equals(id)) {
                modification.accept(group);
                // Added buffs start out as missing
                refreshPresence(group);
                GroupOverlay overlay = overlays.get(id);
                if (overlay != null) {
                    overlay.invalidateLayout();
                }
                changed();
                return;
            }
        }
    }

    void refreshPresence(BuffGroup group) {
        if (group == null) {
            return;
        }
        for (BuffWrapper wrapper : group.getBuffs()) {
            wrapper.setPresent(wrapper.getBuff().isActive(client));
        }
    }

    // The font or icon size changed
    void invalidateLayouts() {
        for (GroupOverlay overlay : overlays.values()) {
            overlay.invalidateLayout();
        }
    }

    // Hidden groups draw nothing, so only the visible group's overlay is added to the overlay manager
    private void addOverlay(BuffGroup group) {
        GroupOverlay overlay = overlayFactory.create(group);
        overlays.put(group.getId(), overlay);
        if (group.isVisible()) {
            overlayManager.add(overlay);
        }
    }

    private void changed() {
        save();
        changeListener.run();
    }

    private void save() {
        // Set before writing, as the write posts a ConfigChanged that reloadIfChanged() compares against
        if (groups.isEmpty()) {
            savedJson = null;
            configManager.unsetConfiguration(ConfigKeys.PLUGIN_CONFIG_GROUP_NAME, ConfigKeys.GROUPS);
            return;
        }
        List<SavedGroup> saved = new ArrayList<>(groups.size());
        for (BuffGroup group : groups) {
            saved.add(SavedGroup.fromGroup(group));
        }
        savedJson = gson.toJson(saved);
        configManager.setConfiguration(ConfigKeys.PLUGIN_CONFIG_GROUP_NAME, ConfigKeys.GROUPS, savedJson);
    }
}

package com.github.cubeee.bufftracker;

import com.github.cubeee.bufftracker.model.Buff;
import com.github.cubeee.bufftracker.model.BuffGroup;
import com.github.cubeee.bufftracker.config.ConfigKeys;
import com.github.cubeee.bufftracker.ui.BuffTrackerPanel;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;
import java.util.*;

@Singleton
class PanelController {

    private final ClientToolbar clientToolbar;
    private final ClientThread clientThread;
    private final BuffTrackerConfig config;
    private final BuffIconStore iconStore;
    private final GroupStore groupStore;
    private final GroupActions groupActions;

    private BuffTrackerPanel panel;
    private NavigationButton navigationButton;
    // Client thread only; icons finishing in the same client cycle share one panel rebuild
    private boolean iconRefreshPending;

    @Inject
    PanelController(
            ClientToolbar clientToolbar,
            ClientThread clientThread,
            BuffTrackerConfig config,
            BuffIconStore iconStore,
            GroupStore groupStore,
            GroupActions groupActions
    ) {
        this.clientToolbar = clientToolbar;
        this.clientThread = clientThread;
        this.config = config;
        this.iconStore = iconStore;
        this.groupStore = groupStore;
        this.groupActions = groupActions;
    }

    void startUp() {
        panel = new BuffTrackerPanel(groupActions);

        BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/panel_icon.png");

        navigationButton = NavigationButton.builder()
                .tooltip("Buff Tracker")
                .priority(config.getPanelPriority())
                .panel(panel)
                .icon(icon)
                .build();

        if (config.showPanel()) {
            clientToolbar.addNavigation(navigationButton);
        }
    }

    void shutDown() {
        clientToolbar.removeNavigation(navigationButton);
        navigationButton = null;
        panel = null;
    }

    void onConfigChanged(String key) {
        if (navigationButton == null) {
            return;
        }

        if (ConfigKeys.SHOW_PANEL.equals(key)) {
            if (config.showPanel()) {
                clientToolbar.addNavigation(navigationButton);
            } else {
                clientToolbar.removeNavigation(navigationButton);
            }
        }

        if (ConfigKeys.PANEL_PRIORITY.equals(key)) {
            recreateNavigationButton();
        }
    }

    // The new profile may hide the panel or give it another priority
    void onProfileChanged() {
        if (navigationButton != null) {
            recreateNavigationButton();
        }
    }

    // Called on the client thread; the panel is only touched on the EDT, where the plugin starts and stops
    void refreshIcons() {
        if (iconRefreshPending) {
            return;
        }
        iconRefreshPending = true;
        clientThread.invokeLater(() -> {
            iconRefreshPending = false;
            Map<Buff, BufferedImage> images = iconStore.snapshot();
            SwingUtilities.invokeLater(() -> {
                if (panel != null) {
                    panel.setIcons(images);
                }
            });
        });
    }

    void refreshGroups() {
        List<BuffGroup> groups = groupStore.snapshot();
        SwingUtilities.invokeLater(() -> {
            if (panel != null) {
                panel.setGroups(groups);
            }
        });
    }

    // The groups were replaced, e.g. by another profile's
    void replaceGroups() {
        List<BuffGroup> groups = groupStore.snapshot();
        SwingUtilities.invokeLater(() -> {
            if (panel != null) {
                panel.replaceGroups(groups);
            }
        });
    }

    private void recreateNavigationButton() {
        clientToolbar.removeNavigation(navigationButton);
        navigationButton = NavigationButton.builder()
                .tooltip(navigationButton.getTooltip())
                .priority(config.getPanelPriority())
                .panel(navigationButton.getPanel())
                .icon(navigationButton.getIcon())
                .build();
        if (config.showPanel()) {
            clientToolbar.addNavigation(navigationButton);
        }
    }
}

