package com.github.cubeee.bufftracker.model;

import com.github.cubeee.bufftracker.config.DisplayMode;
import net.runelite.client.ui.overlay.components.ComponentOrientation;

import java.util.*;

public class SavedGroup {

    String id;
    String name;
    DisplayMode displayMode;
    boolean visible;
    boolean reversed;
    ComponentOrientation orientation;
    boolean missingOnly;
    boolean flashMissing;
    List<String> buffs;

    public static SavedGroup fromGroup(BuffGroup group) {
        SavedGroup saved = new SavedGroup();
        saved.id = group.getId();
        saved.name = group.getName();
        saved.displayMode = group.getDisplayMode();
        saved.visible = group.isVisible();
        saved.reversed = group.isReversed();
        saved.orientation = group.getOrientation();
        saved.missingOnly = group.isMissingOnly();
        saved.flashMissing = group.isFlashMissing();
        saved.buffs = new ArrayList<>();
        for (BuffWrapper wrapper : group.getBuffs()) {
            saved.buffs.add(wrapper.getBuff().name());
        }
        return saved;
    }

    public BuffGroup toGroup() {
        BuffGroup group = new BuffGroup(
                // The id also names the overlay, so a group without one gets a fresh id and position
                id != null && !id.isEmpty() ? id : UUID.randomUUID().toString(),
                toName(),
                displayMode != null ? displayMode : BuffGroup.DEFAULT_DISPLAY_MODE,
                visible,
                reversed,
                orientation != null ? orientation : BuffGroup.DEFAULT_ORIENTATION,
                toWrappers()
        );
        group.setMissingOnly(missingOnly);
        group.setFlashMissing(flashMissing);
        return group;
    }

    // Hand-edited data may hold a name longer than the panel allows typing
    private String toName() {
        if (name == null) {
            return "Group";
        }
        return name.length() > BuffGroup.MAX_NAME_LENGTH ? name.substring(0, BuffGroup.MAX_NAME_LENGTH) : name;
    }

    private List<BuffWrapper> toWrappers() {
        List<BuffWrapper> wrappers = new ArrayList<>();
        if (buffs == null) {
            return wrappers;
        }
        for (String buffId : buffs) {
            Buff buff = Buff.fromId(buffId);
            // Skip buffs that have since been removed, and duplicates from hand-edited data
            if (buff != null && wrappers.stream().noneMatch(wrapper -> wrapper.getBuff() == buff)) {
                wrappers.add(new BuffWrapper(buff, false));
            }
        }
        return wrappers;
    }
}

package com.github.cubeee.bufftracker.overlay;

import com.google.common.base.Strings;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.overlay.components.BackgroundComponent;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.RenderableEntity;
import net.runelite.client.ui.overlay.components.TextComponent;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;

@Setter
public class BuffComponent implements RenderableEntity {

    private Font font;
    private int padding;
    private String text;
    private Color backgroundColor = ComponentConstants.STANDARD_BACKGROUND_COLOR;
    private BufferedImage image;
    // Width of the icon slot; images are centered in it so text lines up across boxes
    private int iconSize;

    private Dimension preferredSize;

    // Position within the overlay, and the area last drawn there
    @Getter
    private final Rectangle bounds = new Rectangle();
    private int locationX;
    private int locationY;

    // Rendered every frame, so reused instead of recreated
    private final BackgroundComponent backgroundComponent = new BackgroundComponent();
    private final TextComponent textComponent = new TextComponent();

    public void setLocation(int locationX, int locationY) {
        this.locationX = locationX;
        this.locationY = locationY;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        final int baseX = locationX;
        final int baseY = locationY;

        // Calculate dimensions
        bounds.setBounds(baseX, baseY, preferredSize.width, preferredSize.height);

        // Render background
        backgroundComponent.setBackgroundColor(backgroundColor);
        backgroundComponent.setRectangle(bounds);
        backgroundComponent.render(graphics);

        if (image != null) {
            int slotWidth = Math.max(iconSize, image.getWidth());
            int imageX = baseX + padding + (slotWidth - image.getWidth()) / 2;
            int imageY = baseY + (bounds.height - image.getHeight()) / 2;
            graphics.drawImage(image, imageX, imageY, null);
        }

        int offsetX = image != null ? Math.max(iconSize, image.getWidth()) + padding * 2 : padding;

        // Render caption
        if (!Strings.isNullOrEmpty(text))
        {
            graphics.setFont(font);
            FontMetrics fontMetrics = graphics.getFontMetrics();
            // Baseline that centres the text's full height vertically
            int textY = baseY + (bounds.height - fontMetrics.getHeight()) / 2 + fontMetrics.getAscent();

            // TextComponent's default white, unoutlined text
            textComponent.setText(text);
            textComponent.setPosition(baseX + offsetX, textY);
            textComponent.render(graphics);
        }

        return preferredSize;
    }
}

package com.github.cubeee.bufftracker.ui;

import com.github.cubeee.bufftracker.model.Buff;
import net.runelite.client.util.ImageUtil;

import javax.swing.ImageIcon;
import java.awt.image.BufferedImage;
import java.util.*;

class BuffCatalog {

    static final int ICON_SIZE = 24;

    // BufferedImage uses identity equality, so replaced images drop their icons once unreferenced
    private final Map<BufferedImage, ImageIcon> scaledIcons = new WeakHashMap<>();

    private Map<Buff, BufferedImage> images = Collections.emptyMap();

    void setImages(Map<Buff, BufferedImage> images) {
        this.images = images;
    }

    static Comparator<Buff> byName() {
        return Comparator.comparing(Buff::getName, String.CASE_INSENSITIVE_ORDER);
    }

    /**
     * Returns null while the buff's item image is still loading.
     */
    ImageIcon getIcon(Buff buff) {
        BufferedImage image = images.get(buff);
        if (image == null) {
            return null;
        }
        return scaledIcons.computeIfAbsent(image,
                img -> new ImageIcon(ImageUtil.resizeImage(img, ICON_SIZE, ICON_SIZE, true)));
    }
}

