package com.github.cubeee.bufftracker.ui;

import com.github.cubeee.bufftracker.GroupActions;
import com.github.cubeee.bufftracker.model.Buff;
import com.github.cubeee.bufftracker.model.BuffGroup;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

import javax.annotation.Nonnull;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.*;

public class BuffTrackerPanel extends PluginPanel {

    private final GroupActions actions;
    private final BuffCatalog catalog = new BuffCatalog();

    private final JPanel groupsPanel = new JPanel();

    private final Set<String> expandedGroupIds = new HashSet<>();
    private List<BuffGroup> groups = Collections.emptyList();
    private Set<String> knownGroupIds;
    // The cards currently shown, by group id
    private final Map<String, GroupCard> cards = new HashMap<>();

    // A group name is being edited. Rebuilding would remove the field and drop the edit, so wait for it to end.
    private boolean editing;
    private boolean rebuildPending;

    public BuffTrackerPanel(GroupActions groupActions) {
        super(false);
        this.actions = groupActions;

        setLayout(new BorderLayout());
        setBorder(new EmptyBorder(10, 10, 10, 10));

        add(getHeader(), BorderLayout.NORTH);
        add(createGroupsList(), BorderLayout.CENTER);

        rebuildGroups();
    }

    @Nonnull
    private JPanel getHeader() {
        JLabel title = new JLabel("Buff Tracker");
        title.setForeground(Color.WHITE);

        JButton addGroupButton = new JButton("+");
        addGroupButton.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
        addGroupButton.setToolTipText("Add group");
        addGroupButton.setFocusPainted(false);
        addGroupButton.addActionListener(e -> actions.createGroup());

        JPanel header = new JPanel(new BorderLayout());
        header.setBorder(new EmptyBorder(0, 0, 8, 0));
        header.add(title, BorderLayout.WEST);
        header.add(addGroupButton, BorderLayout.EAST);
        return header;
    }

    private JComponent createGroupsList() {
        groupsPanel.setLayout(new BoxLayout(groupsPanel, BoxLayout.Y_AXIS));

        JScrollPane scrollPane = new JScrollPane(new ViewportWidthPanel(groupsPanel));
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setBorder(BorderFactory.createEmptyBorder());

        return scrollPane;
    }

    public void setGroups(List<BuffGroup> groups) {
        trackExpandedGroups(groups);

        List<BuffGroup> oldGroups = this.groups;
        this.groups = groups;
        if (rebuildPending || !haveSameIds(oldGroups, groups)) {
            rebuildGroups();
        } else {
            updateCards(oldGroups, groups);
        }
    }

    private void trackExpandedGroups(List<BuffGroup> groups) {
        Set<String> ids = new HashSet<>();
        for (BuffGroup group : groups) {
            ids.add(group.getId());
            // New groups start expanded
            if (knownGroupIds != null && !knownGroupIds.contains(group.getId())) {
                expandedGroupIds.add(group.getId());
            }
        }
        expandedGroupIds.retainAll(ids);
        knownGroupIds = ids;
    }

    /**
     * Updates the cards for the same groups in the same order. Usually a single group was edited. Toggling
     * visibility, e.g. with the hotkeys, only needs the eye buttons updated; other changes replace just the changed
     * cards.
     */
    private void updateCards(List<BuffGroup> oldGroups, List<BuffGroup> groups) {
        List<BuffGroup> changed = new ArrayList<>();
        for (int i = 0; i < groups.size(); i++) {
            BuffGroup group = groups.get(i);
            if (oldGroups.get(i).equalsIgnoringVisibility(group)) {
                cards.get(group.getId()).setGroupVisible(group.isVisible());
            } else {
                changed.add(group);
            }
        }
        if (changed.isEmpty()) {
            return;
        }
        if (editing) {
            // The edited name field may be in one of the cards
            rebuildGroups();
            return;
        }
        for (BuffGroup group : changed) {
            replaceCard(group);
        }
        groupsPanel.revalidate();
        groupsPanel.repaint();
    }

    /**
     * Shows a different set of groups, e.g. another profile's, all collapsed.
     */
    public void replaceGroups(List<BuffGroup> groups) {
        knownGroupIds = null;
        expandedGroupIds.clear();
        // Expanded cards must be rebuilt collapsed, even if the new groups only differ in visibility
        rebuildPending = true;
        setGroups(groups);
    }

    // Same groups in the same order, so each card can be updated in place
    private static boolean haveSameIds(List<BuffGroup> oldGroups, List<BuffGroup> newGroups) {
        if (oldGroups.size() != newGroups.size()) {
            return false;
        }
        for (int i = 0; i < oldGroups.size(); i++) {
            if (!oldGroups.get(i).getId().equals(newGroups.get(i).getId())) {
                return false;
            }
        }
        return true;
    }

    public void setIcons(Map<Buff, BufferedImage> images) {
        catalog.setImages(images);
        if (!canReplaceCards()) {
            rebuildGroups();
            return;
        }
        // Only expanded cards show buff icons
        for (BuffGroup group : groups) {
            if (expandedGroupIds.contains(group.getId())) {
                replaceCard(group);
            }
        }
        groupsPanel.revalidate();
        groupsPanel.repaint();
    }

    private void setEditing(boolean editing) {
        this.editing = editing;
        if (!editing && rebuildPending) {
            // Called from the field's focus listener; let the focus change finish before the field is removed
            SwingUtilities.invokeLater(this::rebuildGroups);
        }
    }

    private void rebuildGroups() {
        if (editing) {
            rebuildPending = true;
            return;
        }
        rebuildPending = false;

        groupsPanel.removeAll();
        cards.clear();

        if (groups.isEmpty()) {
            JLabel emptyLabel = new JLabel("No groups, click + to add one");
            emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
            groupsPanel.add(emptyLabel);
        }

        for (BuffGroup group : groups) {
            GroupCard card = createCard(group);
            cards.put(group.getId(), card);
            groupsPanel.add(card);
            groupsPanel.add(Box.createVerticalStrut(4));
        }

        groupsPanel.revalidate();
        groupsPanel.repaint();
    }

    private GroupCard createCard(BuffGroup group) {
        String id = group.getId();
        Runnable toggle = () -> {
            if (!expandedGroupIds.remove(id)) {
                expandedGroupIds.add(id);
            }
            if (!canReplaceCards()) {
                rebuildGroups();
                return;
            }
            // The card's own group may be outdated, e.g. after a visibility-only update
            for (BuffGroup current : groups) {
                if (current.getId().equals(id)) {
                    replaceCard(current);
                }
            }
            groupsPanel.revalidate();
            groupsPanel.repaint();
        };
        return new GroupCard(group, expandedGroupIds.contains(id), toggle, this::setEditing, actions, catalog);
    }

    // The cards match the groups and no name field would be removed mid-edit
    private boolean canReplaceCards() {
        return !editing && !rebuildPending;
    }

    /**
     * Swaps a card for a new one built from the group; the caller revalidates the panel.
     */
    private void replaceCard(BuffGroup group) {
        GroupCard oldCard = cards.get(group.getId());
        int index = groupsPanel.getComponentZOrder(oldCard);
        GroupCard card = createCard(group);
        groupsPanel.remove(index);
        groupsPanel.add(card, index);
        cards.put(group.getId(), card);
    }
}

package com.github.cubeee.bufftracker.ui;

import net.runelite.client.ui.ColorScheme;

import javax.swing.ImageIcon;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

final class EyeIcons {

    private static final int SIZE = 16;

    private static final Color VISIBLE_COLOR = Color.WHITE;
    private static final Color HIDDEN_COLOR = ColorScheme.MEDIUM_GRAY_COLOR;
    private static final Color HOVER_COLOR = ColorScheme.LIGHT_GRAY_COLOR;

    static final ImageIcon VISIBLE = new ImageIcon(draw(VISIBLE_COLOR, false));
    static final ImageIcon VISIBLE_HOVER = new ImageIcon(draw(HOVER_COLOR, false));
    static final ImageIcon HIDDEN = new ImageIcon(draw(HIDDEN_COLOR, true));
    static final ImageIcon HIDDEN_HOVER = new ImageIcon(draw(HOVER_COLOR, true));

    private EyeIcons() {
    }

    private static BufferedImage draw(Color color, boolean crossedOut) {
        BufferedImage image = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try {
            graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
            graphics.setColor(color);
            graphics.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));

            // Almond-shaped outline
            Path2D outline = new Path2D.Double();
            outline.moveTo(1.5, 8);
            outline.quadTo(8, 1, 14.5, 8);
            outline.quadTo(8, 15, 1.5, 8);
            outline.closePath();
            graphics.draw(outline);

            // Pupil
            graphics.fill(new Ellipse2D.Double(5.5, 5.5, 5, 5));

            if (crossedOut) {
                graphics.draw(new Line2D.Double(2.5, 13.5, 13.5, 2.5));
            }
        } finally {
            graphics.dispose();
        }
        return image;
    }
}

package com.github.cubeee.bufftracker.ui;

import com.github.cubeee.bufftracker.GroupActions;
import com.github.cubeee.bufftracker.model.Buff;
import com.github.cubeee.bufftracker.model.BuffGroup;
import com.github.cubeee.bufftracker.model.BuffWrapper;
import com.github.cubeee.bufftracker.config.DisplayMode;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.components.ComponentOrientation;

import javax.annotation.Nonnull;
import javax.swing.AbstractButton;
import javax.swing.BoxLayout;
import javax.swing.ButtonGroup;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JToggleButton;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.GridLayout;
import java.awt.Insets;
import java.util.*;
import java.util.function.*;

class GroupCard extends JPanel {

    // RuneLite's default font lacks arrow glyphs
    private static final Font SYMBOL_FONT = new Font(Font.DIALOG, Font.PLAIN, 11);

    private enum Direction {
        RIGHT("→", "Horizontal", ComponentOrientation.HORIZONTAL, false),
        LEFT("←", "Horizontal, reversed", ComponentOrientation.HORIZONTAL, true),
        DOWN("↓", "Vertical", ComponentOrientation.VERTICAL, false),
        UP("↑", "Vertical, reversed", ComponentOrientation.VERTICAL, true);

        private final String symbol;
        private final String tooltip;
        private final ComponentOrientation orientation;
        private final boolean reversed;

        Direction(String symbol, String tooltip, ComponentOrientation orientation, boolean reversed) {
            this.symbol = symbol;
            this.tooltip = tooltip;
            this.orientation = orientation;
            this.reversed = reversed;
        }
    }

    private final BuffGroup group;
    private final GroupActions actions;
    private final BuffCatalog catalog;

    private JToggleButton visibleButton;
    private InlineTextField nameField;

    GroupCard(
            BuffGroup group,
            boolean expanded,
            Runnable onToggleExpanded,
            Consumer<Boolean> onEditingChanged,
            GroupActions actions,
            BuffCatalog catalog
    ) {
        this.group = group;
        this.actions = actions;
        this.catalog = catalog;

        // No vgap: BorderLayout adds it below NORTH even without a CENTER, unbalancing collapsed cards
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(new EmptyBorder(4, 4, 4, 4));

        add(createHeader(expanded, onToggleExpanded, onEditingChanged), BorderLayout.NORTH);
        setGroupVisible(group.isVisible());
        if (expanded) {
            add(createBody(), BorderLayout.CENTER);
        }
    }

    @Override
    public Dimension getMaximumSize() {
        // Stretch horizontally in the BoxLayout, but never vertically
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }

    /**
     * Updates the card in place when only the group's visibility changed.
     */
    final void setGroupVisible(boolean visible) {
        visibleButton.setSelected(visible);
        visibleButton.setToolTipText(visible ? "Hide overlay" : "Show overlay");
        nameField.setForeground(visible ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
    }

    private JPanel createHeader(boolean expanded, Runnable onToggleExpanded, Consumer<Boolean> onEditingChanged) {
        JButton expandButton = symbolButton(expanded ? "▼" : "▶", expanded ? "Collapse" : "Expand");
        expandButton.addActionListener(e -> onToggleExpanded.run());

        visibleButton = createVisibleButton();

        JButton menuButton = symbolButton("…", "More");
        menuButton.addActionListener(e -> {
            JPopupMenu menu = new JPopupMenu();
            JMenuItem delete = new JMenuItem("Delete");
            delete.addActionListener(ev -> confirmDelete());
            menu.add(delete);
            menu.show(menuButton, 0, menuButton.getHeight());
        });

        nameField = new InlineTextField(group.getName(), name -> {
            if (name.isEmpty()) {
                return false;
            }
            actions.setName(group.getId(), name);
            return true;
        }, BuffGroup.MAX_NAME_LENGTH, onEditingChanged);
        nameField.setToolTipText("Click to rename");

        // GridBag centers every component vertically within the row
        JPanel header = new JPanel(new GridBagLayout());
        header.setOpaque(false);
        GridBagConstraints constraints = new GridBagConstraints();
        constraints.gridy = 0;
        constraints.anchor = GridBagConstraints.CENTER;
        constraints.insets = new Insets(0, 0, 0, 2);
        header.add(expandButton, constraints);
        header.add(visibleButton, constraints);
        constraints.weightx = 1;
        constraints.fill = GridBagConstraints.HORIZONTAL;
        header.add(nameField, constraints);
        constraints.weightx = 0;
        constraints.fill = GridBagConstraints.NONE;
        constraints.insets = new Insets(0, 0, 0, 0);
        header.add(menuButton, constraints);
        return header;
    }

    @Nonnull
    private JToggleButton createVisibleButton() {
        JToggleButton visibleButton = new JToggleButton(EyeIcons.HIDDEN);
        visibleButton.setSelectedIcon(EyeIcons.VISIBLE);
        visibleButton.setRolloverIcon(EyeIcons.HIDDEN_HOVER);
        visibleButton.setRolloverSelectedIcon(EyeIcons.VISIBLE_HOVER);
        visibleButton.setBorder(new EmptyBorder(0, 2, 0, 2));
        visibleButton.setContentAreaFilled(false);
        visibleButton.setFocusPainted(false);
        visibleButton.addActionListener(e -> actions.setVisible(group.getId(), visibleButton.isSelected()));
        return visibleButton;
    }

    private JPanel createBody() {
        JPanel body = new JPanel();
        body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
        body.setOpaque(false);
        body.setBorder(new EmptyBorder(6, 0, 0, 0));

        body.add(createSettings());

        List<BuffWrapper> members = group.getBuffs();
        JPanel membersPanel = new JPanel(new GridLayout(0, 1, 0, 2));
        membersPanel.setOpaque(false);
        membersPanel.setBorder(new EmptyBorder(6, 0, 0, 0));
        for (int i = 0; i < members.size(); i++) {
            membersPanel.add(createMemberRow(members.get(i).getBuff(), i == 0, i == members.size() - 1));
        }
        membersPanel.add(createAddButton());

        body.add(membersPanel);
        return body;
    }

    private JPanel createSettings() {
        JComboBox<DisplayMode> displayBox = new JComboBox<>(DisplayMode.values());
        displayBox.setSelectedItem(group.getDisplayMode());
        displayBox.addActionListener(e -> {
            // Also fired when the current mode is picked again
            DisplayMode mode = (DisplayMode) displayBox.getSelectedItem();
            if (mode != group.getDisplayMode()) {
                actions.setDisplayMode(group.getId(), mode);
            }
        });

        // Labels take their natural width, controls get the rest
        JPanel settings = new JPanel(new GridBagLayout());
        settings.setOpaque(false);
        GridBagConstraints constraints = new GridBagConstraints();
        constraints.insets = new Insets(0, 0, 4, 6);
        constraints.anchor = GridBagConstraints.WEST;

        constraints.gridy = 0;
        settings.add(label("Display"), constraints);
        constraints.gridy = 1;
        settings.add(label("Direction"), constraints);

        constraints.gridx = 1;
        constraints.weightx = 1;
        constraints.fill = GridBagConstraints.HORIZONTAL;
        constraints.insets = new Insets(0, 0, 4, 0);
        constraints.gridy = 0;
        settings.add(displayBox, constraints);
        constraints.gridy = 1;
        settings.add(createDirectionButtons(), constraints);

        // Checkboxes span both columns
        constraints.gridx = 0;
        constraints.gridwidth = 2;
        constraints.gridy = 2;
        settings.add(checkBox("Show missing only", "Only show the buffs that are missing",
                group.isMissingOnly(), selected -> actions.setMissingOnly(group.getId(), selected)), constraints);
        constraints.gridy = 3;
        constraints.insets = new Insets(0, 0, 0, 0);
        settings.add(checkBox("Flash missing buffs", "Alternate missing buffs between the missing color and RuneLite's overlay color",
                group.isFlashMissing(), selected -> actions.setFlashMissing(group.getId(), selected)), constraints);
        return settings;
    }

    private static JCheckBox checkBox(String text, String tooltip, boolean selected, Consumer<Boolean> onChange) {
        JCheckBox checkBox = new JCheckBox(text, selected);
        checkBox.setToolTipText(tooltip);
        checkBox.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        checkBox.setOpaque(false);
        checkBox.setFocusPainted(false);
        checkBox.addActionListener(e -> onChange.accept(checkBox.isSelected()));
        return checkBox;
    }

    private JPanel createDirectionButtons() {
        JPanel panel = new JPanel(new GridLayout(1, 0, 2, 0));
        panel.setOpaque(false);

        ButtonGroup buttonGroup = new ButtonGroup();
        for (Direction direction : Direction.values()) {
            JToggleButton button = new JToggleButton(direction.symbol);
            styleSymbolButton(button, direction.tooltip);
            boolean current = group.getOrientation() == direction.orientation && group.isReversed() == direction.reversed;
            button.setSelected(current);
            // Clicking the selected button keeps it selected; nothing changes
            if (!current) {
                button.addActionListener(e -> actions.setDirection(group.getId(), direction.orientation, direction.reversed));
            }
            buttonGroup.add(button);
            panel.add(button);
        }
        return panel;
    }

    private JButton createAddButton() {
        List<Buff> candidates = new ArrayList<>();
        for (Buff buff : Buff.values()) {
            if (!group.contains(buff)) {
                candidates.add(buff);
            }
        }
        candidates.sort(BuffCatalog.byName());

        JButton addButton = new JButton("+ Add buff");
        addButton.setFocusPainted(false);
        if (candidates.isEmpty()) {
            addButton.setEnabled(false);
            addButton.setToolTipText("All buffs are already in this group");
        }
        BuffPicker.attach(addButton, candidates, catalog, buff -> actions.addBuff(group.getId(), buff));
        return addButton;
    }

    private JComponent createMemberRow(Buff buff, boolean first, boolean last) {
        JButton up = symbolButton("▲", "Move up");
        up.setEnabled(!first);
        up.addActionListener(e -> actions.moveBuff(group.getId(), buff, -1));

        JButton down = symbolButton("▼", "Move down");
        down.setEnabled(!last);
        down.addActionListener(e -> actions.moveBuff(group.getId(), buff, 1));

        JButton remove = symbolButton("✕", "Remove from group");
        remove.addActionListener(e -> actions.removeBuff(group.getId(), buff));

        JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 1, 0));
        buttons.add(up);
        buttons.add(down);
        buttons.add(remove);

        BuffRow row = new BuffRow(buff.getName(), catalog.getIcon(buff), buttons);
        row.setBackground(ColorScheme.DARK_GRAY_COLOR);
        return row;
    }

    private void confirmDelete() {
        int result = JOptionPane.showConfirmDialog(this,
                "Delete group \"" + group.getName() + "\"?",
                "Delete group",
                JOptionPane.YES_NO_OPTION);
        if (result == JOptionPane.YES_OPTION) {
            actions.deleteGroup(group.getId());
        }
    }

    private static JLabel label(String text) {
        JLabel label = new JLabel(text);
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        return label;
    }

    private static JButton symbolButton(String text, String tooltip) {
        JButton button = new JButton(text);
        styleSymbolButton(button, tooltip);
        return button;
    }

    private static void styleSymbolButton(AbstractButton button, String tooltip) {
        button.setFont(SYMBOL_FONT);
        button.setToolTipText(tooltip);
        button.setMargin(new Insets(0, 2, 0, 2));
        button.setFocusPainted(false);
    }
}

package com.github.cubeee.bufftracker.ui;

import net.runelite.client.ui.ColorScheme;

import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import javax.swing.border.Border;
import javax.swing.border.EmptyBorder;
import javax.swing.text.AbstractDocument;
import javax.swing.text.AttributeSet;
import javax.swing.text.BadLocationException;
import javax.swing.text.DocumentFilter;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Insets;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.*;

/**
 * While idle, the field paints a JLabel instead of itself so that long text is truncated with an ellipsis at the end
 * (a JTextField would instead scroll to show the end of the text). Clicking it focuses it the usual Swing way, which
 * starts the edit.
 */
class InlineTextField extends JPanel {

    private static final Border IDLE_BORDER = new EmptyBorder(2, 2, 2, 2);
    private static final Border EDIT_BORDER = BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
            new EmptyBorder(1, 1, 1, 1));

    private final JLabel label;
    private final JTextField field;
    private final String text;
    private final Predicate<String> onCommit;
    private final Consumer<Boolean> onEditingChanged;
    // Between starting the edit and committing or dropping it
    private boolean editing;

    /**
     * @param maxLength longer input, e.g. pasted text, is cut off
     * @param onEditingChanged told when editing starts and ends, so the owner can avoid removing the field mid-edit
     */
    InlineTextField(String text, Predicate<String> onCommit, int maxLength, Consumer<Boolean> onEditingChanged) {
        this.text = text;
        this.onCommit = onCommit;
        this.onEditingChanged = onEditingChanged;
        setLayout(new BorderLayout());
        setOpaque(false);

        label = new JLabel(text);
        // Text starting with <html> would otherwise be rendered as HTML, which can load remote images
        label.putClientProperty("html.disable", Boolean.TRUE);

        field = new JTextField(text) {
            @Override
            protected void paintComponent(Graphics graphics) {
                if (editing) {
                    super.paintComponent(graphics);
                    return;
                }
                Insets insets = getInsets();
                SwingUtilities.paintComponent(graphics, label, this, insets.left, insets.top,
                        getWidth() - insets.left - insets.right, getHeight() - insets.top - insets.bottom);
            }
        };
        ((AbstractDocument) field.getDocument()).setDocumentFilter(new LengthFilter(maxLength));
        label.setFont(field.getFont());
        showIdle();

        addListeners();
        add(field, BorderLayout.CENTER);
    }

    private void addListeners() {
        field.addActionListener(e -> commitEdit());
        field.addFocusListener(new FocusAdapter() {
            @Override
            public void focusGained(FocusEvent event) {
                // Not editing after a temporary loss means the edit was ended meanwhile; keep it ended
                if (!editing && !event.isTemporary()) {
                    startEdit();
                }
            }

            @Override
            public void focusLost(FocusEvent event) {
                // A temporary loss is e.g. switching to another window; the field gets focus back with the client
                if (event.isTemporary()) {
                    return;
                }
                if (field.isDisplayable()) {
                    commitEdit();
                } else {
                    dropEdit();
                }
            }
        });
        field.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent event) {
                // Enter and Escape end the edit but leave the field focused, so no focus gain follows a click
                if (!editing && field.isFocusOwner()) {
                    startEdit();
                }
            }
        });
        KeyBindings.bind(field, JComponent.WHEN_FOCUSED, KeyEvent.VK_ESCAPE, "cancelEdit", this::dropEdit);
    }

    private void startEdit() {
        editing = true;
        field.setEditable(true);
        field.setOpaque(true);
        field.setBorder(EDIT_BORDER);
        field.getCaret().setVisible(true);
        field.selectAll();
        field.repaint();
        onEditingChanged.accept(true);
    }

    // Does nothing if the edit already ended, e.g. by Enter or Escape
    private void commitEdit() {
        if (!editing) {
            return;
        }
        String value = field.getText().trim();
        if (value.equals(text) || !onCommit.test(value)) {
            field.setText(text);
        } else {
            // Show the new value until the panel is rebuilt with it
            label.setText(value);
        }
        endEdit();
    }

    /**
     * Ends editing without committing: Escape, or the field was removed mid-edit, e.g. the plugin was turned off.
     */
    private void dropEdit() {
        if (!editing) {
            return;
        }
        field.setText(text);
        endEdit();
    }

    private void endEdit() {
        editing = false;
        showIdle();
        onEditingChanged.accept(false);
    }

    private void showIdle() {
        field.setEditable(false);
        field.setOpaque(false);
        field.setBorder(IDLE_BORDER);
        field.getCaret().setVisible(false);
        // Clears the selection, so the next edit starts from the beginning of the text
        field.setCaretPosition(0);
        field.repaint();
    }

    @Override
    public void removeNotify() {
        super.removeNotify();
        // If focus was temporarily elsewhere, e.g. in another window, no focus loss will follow to end the edit
        dropEdit();
    }

    @Override
    public Dimension getMinimumSize() {
        // Allow shrinking below the text width so the label truncates instead of overflowing
        return new Dimension(0, super.getMinimumSize().height);
    }

    @Override
    public void setForeground(Color color) {
        super.setForeground(color);
        // Called by the JPanel constructor before the children exist
        if (field != null) {
            label.setForeground(color);
            field.setForeground(color);
        }
    }

    @Override
    public void setToolTipText(String text) {
        field.setToolTipText(text);
    }

    private static final class LengthFilter extends DocumentFilter {

        private final int maxLength;

        LengthFilter(int maxLength) {
            this.maxLength = maxLength;
        }

        @Override
        public void insertString(FilterBypass bypass, int offset, String string, AttributeSet attributes)
                throws BadLocationException {
            replace(bypass, offset, 0, string, attributes);
        }

        @Override
        public void replace(FilterBypass bypass, int offset, int length, String string, AttributeSet attributes)
                throws BadLocationException {
            int room = Math.max(0, maxLength - (bypass.getDocument().getLength() - length));
            String allowed = string != null && string.length() > room ? string.substring(0, room) : string;
            super.replace(bypass, offset, length, allowed, attributes);
        }
    }
}

package com.github.cubeee.bufftracker.ui;

import javax.swing.AbstractAction;
import javax.swing.JComponent;
import javax.swing.KeyStroke;
import java.awt.event.ActionEvent;

final class KeyBindings {

    private KeyBindings() {
    }

    /**
     * Runs the action when the key is pressed, using the component's input and action maps.
     *
     * @param condition one of the {@code JComponent.WHEN_*} constants
     * @param name the action map key; unique per component
     */
    static void bind(JComponent component, int condition, int keyCode, String name, Runnable action) {
        component.getInputMap(condition).put(KeyStroke.getKeyStroke(keyCode, 0), name);
        component.getActionMap().put(name, new AbstractAction() {
            @Override
            public void actionPerformed(ActionEvent event) {
                action.run();
            }
        });
    }
}

package com.github.cubeee.bufftracker.ui;

import javax.swing.JPanel;
import javax.swing.Scrollable;
import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Rectangle;

/**
 * Scroll pane view that tracks the viewport width, so children shrink (and labels truncate) instead of
 * scrolling horizontally. The wrapped component sits at the top at its natural height.
 */
class ViewportWidthPanel extends JPanel implements Scrollable {

    ViewportWidthPanel(Component content) {
        super(new BorderLayout());
        add(content, BorderLayout.NORTH);
    }

    @Override
    public Dimension getPreferredScrollableViewportSize() {
        return getPreferredSize();
    }

    @Override
    public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction) {
        return 16;
    }

    @Override
    public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction) {
        return visibleRect.height;
    }

    @Override
    public boolean getScrollableTracksViewportWidth() {
        return true;
    }

    @Override
    public boolean getScrollableTracksViewportHeight() {
        return false;
    }
}

